const html = '<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>FinanciAI - Clinica Vida Popular</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script>
<style>
:root {
  --bg: #0d1b0e;
  --bg2: #132415;
  --bg3: #1a3a1e;
  --accent: #2ecc71;
  --accent2: #27ae60;
  --accent-dim: #1a7a42;
  --text: #e8f5e9;
  --text2: #a5d6a7;
  --text3: #6b9e6e;
  --red: #e74c3c;
  --red-dim: #c0392b;
  --yellow: #f39c12;
  --blue: #3498db;
  --border: #2a4a2e;
  --shadow: rgba(0,0,0,0.4);
}
* { margin:0; padding:0; box-sizing:border-box; }
body { font-family:'Segoe UI',system-ui,-apple-system,sans-serif; background:var(--bg); color:var(--text); min-height:100vh; }
a { color:var(--accent); text-decoration:none; }

/* Header */
.header { background:var(--bg2); border-bottom:2px solid var(--accent-dim); padding:12px 24px; display:flex; align-items:center; justify-content:space-between; position:sticky; top:0; z-index:100; }
.header h1 { font-size:1.3rem; font-weight:700; }
.header h1 span { color:var(--accent); }
.header-right { display:flex; gap:12px; align-items:center; }
.header-right select, .header-right button { background:var(--bg3); color:var(--text); border:1px solid var(--border); padding:6px 12px; border-radius:6px; cursor:pointer; font-size:0.85rem; }
.header-right button:hover { background:var(--accent-dim); }

/* Layout */
.container { max-width:1400px; margin:0 auto; padding:20px; }
.tabs { display:flex; gap:4px; margin-bottom:20px; flex-wrap:wrap; }
.tab { padding:10px 20px; background:var(--bg2); border:1px solid var(--border); border-radius:8px 8px 0 0; cursor:pointer; font-size:0.9rem; color:var(--text2); transition:all .2s; }
.tab:hover { background:var(--bg3); }
.tab.active { background:var(--accent-dim); color:var(--text); border-color:var(--accent); }
.panel { display:none; }
.panel.active { display:block; }

/* Cards */
.cards { display:grid; grid-template-columns:repeat(auto-fit,minmax(200px,1fr)); gap:16px; margin-bottom:24px; }
.card { background:var(--bg2); border:1px solid var(--border); border-radius:12px; padding:20px; position:relative; overflow:hidden; }
.card::before { content:''; position:absolute; top:0; left:0; right:0; height:3px; }
.card.receita::before { background:var(--accent); }
.card.despesa::before { background:var(--red); }
.card.saldo::before { background:var(--blue); }
.card.pending::before { background:var(--yellow); }
.card-label { font-size:0.8rem; color:var(--text3); text-transform:uppercase; letter-spacing:1px; margin-bottom:8px; }
.card-value { font-size:1.8rem; font-weight:700; }
.card-value.positive { color:var(--accent); }
.card-value.negative { color:var(--red); }
.card-value.neutral { color:var(--blue); }

/* Charts */
.charts { display:grid; grid-template-columns:2fr 1fr; gap:20px; margin-bottom:24px; }
.chart-box { background:var(--bg2); border:1px solid var(--border); border-radius:12px; padding:20px; }
.chart-box h3 { font-size:0.95rem; color:var(--text2); margin-bottom:16px; }

/* Table */
.filters { display:flex; gap:10px; flex-wrap:wrap; margin-bottom:16px; align-items:center; }
.filters select, .filters input { background:var(--bg3); color:var(--text); border:1px solid var(--border); padding:8px 12px; border-radius:6px; font-size:0.85rem; }
.filters input[type=date] { width:145px; }
.filters input[type=text] { width:200px; }
.btn { padding:8px 16px; border-radius:6px; border:none; cursor:pointer; font-size:0.85rem; font-weight:600; transition:all .2s; }
.btn-primary { background:var(--accent); color:#000; }
.btn-primary:hover { background:var(--accent2); }
.btn-danger { background:var(--red); color:#fff; }
.btn-danger:hover { background:var(--red-dim); }
.btn-secondary { background:var(--bg3); color:var(--text); border:1px solid var(--border); }
.btn-secondary:hover { background:var(--border); }
.btn-sm { padding:5px 10px; font-size:0.78rem; }

table { width:100%; border-collapse:collapse; }
th,td { padding:10px 12px; text-align:left; border-bottom:1px solid var(--border); font-size:0.85rem; }
th { background:var(--bg3); color:var(--text2); font-weight:600; text-transform:uppercase; font-size:0.75rem; letter-spacing:0.5px; position:sticky; top:0; }
tr:hover { background:var(--bg3); }
.table-wrap { background:var(--bg2); border:1px solid var(--border); border-radius:12px; overflow:hidden; max-height:500px; overflow-y:auto; }
.badge { padding:3px 8px; border-radius:4px; font-size:0.75rem; font-weight:600; }
.badge-pendente { background:#f39c1233; color:var(--yellow); }
.badge-confirmado { background:#2ecc7133; color:var(--accent); }
.badge-cancelado { background:#e74c3c33; color:var(--red); }
.tipo-receita { color:var(--accent); }
.tipo-despesa { color:var(--red); }

/* Form */
.form-grid { display:grid; grid-template-columns:1fr 1fr; gap:16px; max-width:700px; }
.form-group { display:flex; flex-direction:column; gap:4px; }
.form-group.full { grid-column:1/-1; }
.form-group label { font-size:0.8rem; color:var(--text3); text-transform:uppercase; letter-spacing:0.5px; }
.form-group input, .form-group select, .form-group textarea { background:var(--bg3); color:var(--text); border:1px solid var(--border); padding:10px 12px; border-radius:6px; font-size:0.9rem; }
.form-group textarea { resize:vertical; min-height:80px; }
.form-actions { grid-column:1/-1; display:flex; gap:10px; margin-top:8px; }

/* Upcoming */
.upcoming { background:var(--bg2); border:1px solid var(--border); border-radius:12px; padding:20px; }
.upcoming h3 { font-size:0.95rem; color:var(--text2); margin-bottom:12px; }
.upcoming-item { display:flex; justify-content:space-between; align-items:center; padding:10px 0; border-bottom:1px solid var(--border); }
.upcoming-item:last-child { border-bottom:none; }
.upcoming-date { font-size:0.8rem; color:var(--yellow); font-weight:600; min-width:85px; }
.upcoming-desc { flex:1; margin:0 12px; font-size:0.85rem; }
.upcoming-valor { font-weight:700; color:var(--red); }

/* Modal */
.modal-overlay { display:none; position:fixed; top:0; left:0; right:0; bottom:0; background:rgba(0,0,0,0.7); z-index:200; align-items:center; justify-content:center; }
.modal-overlay.active { display:flex; }
.modal { background:var(--bg2); border:1px solid var(--border); border-radius:12px; padding:24px; max-width:700px; width:95%; max-height:90vh; overflow-y:auto; }
.modal h2 { margin-bottom:16px; font-size:1.1rem; }
.modal .close-btn { float:right; cursor:pointer; font-size:1.2rem; color:var(--text3); background:none; border:none; }

/* Loading */
.loading { text-align:center; padding:40px; color:var(--text3); }
.spinner { display:inline-block; width:24px; height:24px; border:3px solid var(--border); border-top-color:var(--accent); border-radius:50%; animation:spin 0.8s linear infinite; }
@keyframes spin { to { transform:rotate(360deg); } }

/* Toast */
.toast { position:fixed; bottom:20px; right:20px; background:var(--accent-dim); color:var(--text); padding:12px 20px; border-radius:8px; z-index:300; display:none; font-size:0.9rem; box-shadow:0 4px 12px var(--shadow); }
.toast.error { background:var(--red-dim); }
.toast.show { display:block; animation:slideIn .3s ease; }
@keyframes slideIn { from { transform:translateY(20px); opacity:0; } to { transform:translateY(0); opacity:1; } }

/* Responsive */
@media(max-width:768px) {
  .charts { grid-template-columns:1fr; }
  .form-grid { grid-template-columns:1fr; }
  .filters { flex-direction:column; }
  .header { flex-direction:column; gap:10px; }
  .tabs { overflow-x:auto; flex-wrap:nowrap; }
  .card-value { font-size:1.4rem; }
}
</style>
</head>
<body>

<div class="header">
  <h1><span>Financi</span>AI <small style="font-weight:400;font-size:0.8rem;color:var(--text3)">Clinica Vida Popular</small></h1>
  <div class="header-right">
    <select id="periodoMes" onchange="loadDashboard()"></select>
    <button onclick="exportCSV()">Exportar CSV</button>
  </div>
</div>

<div class="container">
  <div class="tabs">
    <div class="tab active" onclick="switchTab('dashboard')">Dashboard</div>
    <div class="tab" onclick="switchTab('lancamentos')">Lancamentos</div>
    <div class="tab" onclick="switchTab('novo')">+ Novo Lancamento</div>
    <div class="tab" onclick="switchTab('categorias')">Categorias</div>
  </div>

  <!-- DASHBOARD -->
  <div id="tab-dashboard" class="panel active">
    <div class="cards" id="cards"></div>
    <div class="charts">
      <div class="chart-box">
        <h3>Receitas vs Despesas (mensal)</h3>
        <canvas id="chartBar"></canvas>
      </div>
      <div class="chart-box">
        <h3>Despesas por Categoria</h3>
        <canvas id="chartPie"></canvas>
      </div>
    </div>
    <div class="upcoming" id="upcoming">
      <h3>Proximos Vencimentos</h3>
      <div class="loading"><div class="spinner"></div></div>
    </div>
  </div>

  <!-- LANCAMENTOS -->
  <div id="tab-lancamentos" class="panel">
    <div class="filters">
      <select id="fTipo" onchange="loadLancamentos()">
        <option value="">Todos os tipos</option>
        <option value="a_pagar">A Pagar</option>
        <option value="a_receber">A Receber</option>
        <option value="pago">Pago</option>
        <option value="recebido">Recebido</option>
      </select>
      <select id="fStatus" onchange="loadLancamentos()">
        <option value="">Todos os status</option>
        <option value="pendente">Pendente</option>
        <option value="confirmado">Confirmado</option>
      </select>
      <select id="fCategoria" onchange="loadLancamentos()">
        <option value="">Todas categorias</option>
      </select>
      <input type="date" id="fDe" onchange="loadLancamentos()" title="De">
      <input type="date" id="fAte" onchange="loadLancamentos()" title="Ate">
      <button class="btn btn-secondary btn-sm" onclick="clearFilters()">Limpar</button>
    </div>
    <div class="table-wrap">
      <table>
        <thead>
          <tr>
            <th>Tipo</th>
            <th>Descricao</th>
            <th>Categoria</th>
            <th>Valor</th>
            <th>Vencimento</th>
            <th>Status</th>
            <th>Acoes</th>
          </tr>
        </thead>
        <tbody id="tblBody">
          <tr><td colspan="7" class="loading"><div class="spinner"></div></td></tr>
        </tbody>
      </table>
    </div>
  </div>

  <!-- NOVO LANCAMENTO -->
  <div id="tab-novo" class="panel">
    <h2 style="margin-bottom:20px;font-size:1.1rem;">Novo Lancamento</h2>
    <form id="formNovo" onsubmit="return criarLancamento(event)">
      <div class="form-grid">
        <div class="form-group">
          <label>Tipo *</label>
          <select name="tipo" required>
            <option value="">Selecione...</option>
            <option value="a_pagar">A Pagar</option>
            <option value="a_receber">A Receber</option>
            <option value="pago">Pago</option>
            <option value="recebido">Recebido</option>
          </select>
        </div>
        <div class="form-group">
          <label>Categoria</label>
          <select name="categoria_id" id="selCategoria"></select>
        </div>
        <div class="form-group full">
          <label>Descricao *</label>
          <input type="text" name="descricao" required placeholder="Ex: Aluguel sala 3">
        </div>
        <div class="form-group">
          <label>Valor (R$) *</label>
          <input type="number" name="valor" step="0.01" min="0.01" required placeholder="0.00">
        </div>
        <div class="form-group">
          <label>Vencimento</label>
          <input type="date" name="vencimento">
        </div>
        <div class="form-group">
          <label>Fornecedor</label>
          <input type="text" name="fornecedor" placeholder="Nome do fornecedor">
        </div>
        <div class="form-group">
          <label>Cliente</label>
          <input type="text" name="cliente" placeholder="Nome do cliente">
        </div>
        <div class="form-group">
          <label>Numero Documento</label>
          <input type="text" name="numero_doc" placeholder="NF, boleto, etc">
        </div>
        <div class="form-group full">
          <label>Observacoes</label>
          <textarea name="observacoes" placeholder="Notas adicionais..."></textarea>
        </div>
        <div class="form-actions">
          <button type="submit" class="btn btn-primary">Salvar Lancamento</button>
          <button type="reset" class="btn btn-secondary">Limpar</button>
        </div>
      </div>
    </form>
  </div>

  <!-- CATEGORIAS -->
  <div id="tab-categorias" class="panel">
    <h2 style="margin-bottom:20px;font-size:1.1rem;">Categorias</h2>
    <div class="table-wrap">
      <table>
        <thead><tr><th>ID</th><th>Nome</th><th>Tipo</th></tr></thead>
        <tbody id="tblCats">
          <tr><td colspan="3" class="loading"><div class="spinner"></div></td></tr>
        </tbody>
      </table>
    </div>
  </div>
</div>

<!-- Modal Edit -->
<div class="modal-overlay" id="modalEdit">
  <div class="modal">
    <button class="close-btn" onclick="closeModal()">&times;</button>
    <h2>Editar Lancamento</h2>
    <form id="formEdit" onsubmit="return updateLancamento(event)">
      <input type="hidden" name="id">
      <div class="form-grid">
        <div class="form-group">
          <label>Tipo</label>
          <select name="tipo">
            <option value="a_pagar">A Pagar</option>
            <option value="a_receber">A Receber</option>
            <option value="pago">Pago</option>
            <option value="recebido">Recebido</option>
          </select>
        </div>
        <div class="form-group">
          <label>Status</label>
          <select name="status">
            <option value="pendente">Pendente</option>
            <option value="confirmado">Confirmado</option>
          </select>
        </div>
        <div class="form-group full">
          <label>Descricao</label>
          <input type="text" name="descricao">
        </div>
        <div class="form-group">
          <label>Valor (R$)</label>
          <input type="number" name="valor" step="0.01">
        </div>
        <div class="form-group">
          <label>Vencimento</label>
          <input type="date" name="vencimento">
        </div>
        <div class="form-group">
          <label>Categoria</label>
          <select name="categoria_id" id="editCategoria"></select>
        </div>
        <div class="form-actions">
          <button type="submit" class="btn btn-primary">Salvar</button>
          <button type="button" class="btn btn-secondary" onclick="closeModal()">Cancelar</button>
        </div>
      </div>
    </form>
  </div>
</div>

<!-- Toast -->
<div class="toast" id="toast"></div>

<script>
const API_BASE = 'https://whatsclinica-n8n.3fraeq.easypanel.host/webhook/api/financeiro';

let categorias = [];
let barChart = null;
let pieChart = null;

// ========== INIT ==========
document.addEventListener('DOMContentLoaded', () => {
  initPeriodos();
  loadCategorias().then(() => {
    loadDashboard();
    loadLancamentos();
  });
});

function initPeriodos() {
  const sel = document.getElementById('periodoMes');
  const now = new Date();
  for (let i = 0; i < 12; i++) {
    const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
    const val = d.toISOString().slice(0, 7);
    const label = d.toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' });
    sel.innerHTML += `<option value="${val}">${label}</option>`;
  }
}

function getperiodo() {
  const val = document.getElementById('periodoMes').value;
  const [y, m] = val.split('-').map(Number);
  const de = `${y}-${String(m).padStart(2, '0')}-01`;
  const last = new Date(y, m, 0).getDate();
  const ate = `${y}-${String(m).padStart(2, '0')}-${last}`;
  return { de, ate };
}

// ========== API ==========
async function api(params) {
  const qs = new URLSearchParams(params).toString();
  const url = `${API_BASE}?${qs}`;
  const res = await fetch(url);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.json();
}

async function apiPost(body) {
  const res = await fetch(API_BASE, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body)
  });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.json();
}

// ========== TABS ==========
function switchTab(name) {
  document.querySelectorAll('.tab').forEach((t, i) => {
    t.classList.toggle('active', t.textContent.toLowerCase().includes(name.slice(0, 4)) ||
      (name === 'novo' && t.textContent.includes('Novo')) ||
      (name === 'categorias' && t.textContent.includes('Categoria')));
  });
  document.querySelectorAll('.panel').forEach(p => p.classList.remove('active'));
  document.getElementById('tab-' + name).classList.add('active');

  if (name === 'lancamentos') loadLancamentos();
  if (name === 'categorias') loadCategoriasTab();
}

// ========== DASHBOARD ==========
async function loadDashboard() {
  const { de, ate } = getperiodo();
  try {
    const [resumo, upcoming] = await Promise.all([
      api({ action: 'resumo', de, ate }),
      api({ action: 'list', tipo: 'a_pagar', status: 'pendente' })
    ]);

    renderCards(Array.isArray(resumo) ? resumo[0] : resumo);
    renderUpcoming(Array.isArray(upcoming) ? upcoming : [upcoming]);
    renderCharts(de, ate);
  } catch (e) {
    console.error('Dashboard error:', e);
    toast('Erro ao carregar dashboard: ' + e.message, true);
  }
}

function renderCards(r) {
  if (!r) return;
  const saldo = parseFloat(r.saldo_previsto || 0);
  document.getElementById('cards').innerHTML = `
    <div class="card pending">
      <div class="card-label">A Pagar (pendente)</div>
      <div class="card-value negative">R$ ${fmt(r.a_pagar_pendente)}</div>
    </div>
    <div class="card pending">
      <div class="card-label">A Receber (pendente)</div>
      <div class="card-value positive">R$ ${fmt(r.a_receber_pendente)}</div>
    </div>
    <div class="card despesa">
      <div class="card-label">Total Despesas</div>
      <div class="card-value negative">R$ ${fmt(r.total_despesas)}</div>
    </div>
    <div class="card receita">
      <div class="card-label">Total Receitas</div>
      <div class="card-value positive">R$ ${fmt(r.total_receitas)}</div>
    </div>
    <div class="card saldo">
      <div class="card-label">Saldo Previsto</div>
      <div class="card-value ${saldo >= 0 ? 'positive' : 'negative'}">R$ ${fmt(r.saldo_previsto)}</div>
    </div>
  `;
}

function renderUpcoming(items) {
  const upcoming = items
    .filter(i => i.vencimento && new Date(i.vencimento) >= new Date(new Date().toDateString()))
    .sort((a, b) => new Date(a.vencimento) - new Date(b.vencimento))
    .slice(0, 8);

  const el = document.getElementById('upcoming');
  if (upcoming.length === 0) {
    el.innerHTML = '<h3>Proximos Vencimentos</h3><p style="color:var(--text3);padding:12px 0">Nenhuma conta pendente com vencimento proximo.</p>';
    return;
  }
  el.innerHTML = '<h3>Proximos Vencimentos</h3>' + upcoming.map(i => `
    <div class="upcoming-item">
      <span class="upcoming-date">${fmtDate(i.vencimento)}</span>
      <span class="upcoming-desc">${i.descricao || i.categoria_nome || '-'}</span>
      <span class="upcoming-valor">R$ ${fmt(i.valor)}</span>
    </div>
  `).join('');
}

async function renderCharts(de, ate) {
  try {
    const data = await api({ action: 'list', de, ate });
    const items = Array.isArray(data) ? data : [data];

    // Bar chart data
    const receitas = items.filter(i => ['a_receber', 'recebido'].includes(i.tipo)).reduce((s, i) => s + parseFloat(i.valor), 0);
    const despesas = items.filter(i => ['a_pagar', 'pago'].includes(i.tipo)).reduce((s, i) => s + parseFloat(i.valor), 0);

    if (barChart) barChart.destroy();
    barChart = new Chart(document.getElementById('chartBar'), {
      type: 'bar',
      data: {
        labels: ['Receitas', 'Despesas'],
        datasets: [{
          data: [receitas, despesas],
          backgroundColor: ['#2ecc7188', '#e74c3c88'],
          borderColor: ['#2ecc71', '#e74c3c'],
          borderWidth: 2,
          borderRadius: 6
        }]
      },
      options: {
        responsive: true,
        plugins: { legend: { display: false } },
        scales: {
          y: { beginAtZero: true, ticks: { color: '#6b9e6e', callback: v => 'R$ ' + v.toLocaleString('pt-BR') }, grid: { color: '#2a4a2e' } },
          x: { ticks: { color: '#a5d6a7' }, grid: { display: false } }
        }
      }
    });

    // Pie chart data
    const catTotals = {};
    items.filter(i => ['a_pagar', 'pago'].includes(i.tipo)).forEach(i => {
      const cat = i.categoria_nome || 'Sem categoria';
      catTotals[cat] = (catTotals[cat] || 0) + parseFloat(i.valor);
    });
    const catLabels = Object.keys(catTotals);
    const catValues = Object.values(catTotals);
    const colors = ['#2ecc71', '#e74c3c', '#3498db', '#f39c12', '#9b59b6', '#1abc9c', '#e67e22', '#34495e', '#16a085', '#c0392b', '#2980b9'];

    if (pieChart) pieChart.destroy();
    pieChart = new Chart(document.getElementById('chartPie'), {
      type: 'doughnut',
      data: {
        labels: catLabels,
        datasets: [{
          data: catValues,
          backgroundColor: colors.slice(0, catLabels.length),
          borderColor: 'var(--bg2)',
          borderWidth: 2
        }]
      },
      options: {
        responsive: true,
        plugins: {
          legend: { position: 'bottom', labels: { color: '#a5d6a7', font: { size: 11 }, padding: 12 } }
        }
      }
    });
  } catch (e) {
    console.error('Charts error:', e);
  }
}

// ========== LANCAMENTOS ==========
async function loadLancamentos() {
  const params = { action: 'list' };
  const tipo = document.getElementById('fTipo').value;
  const status = document.getElementById('fStatus').value;
  const cat = document.getElementById('fCategoria').value;
  const de = document.getElementById('fDe').value;
  const ate = document.getElementById('fAte').value;
  if (tipo) params.tipo = tipo;
  if (status) params.status = status;
  if (cat) params.categoria_id = cat;
  if (de) params.de = de;
  if (ate) params.ate = ate;

  try {
    const data = await api(params);
    const items = Array.isArray(data) ? data : [data];
    renderTable(items.filter(i => i.id));
  } catch (e) {
    document.getElementById('tblBody').innerHTML = `<tr><td colspan="7" style="color:var(--red)">Erro: ${e.message}</td></tr>`;
  }
}

function renderTable(items) {
  if (items.length === 0) {
    document.getElementById('tblBody').innerHTML = '<tr><td colspan="7" style="color:var(--text3)">Nenhum lancamento encontrado.</td></tr>';
    return;
  }
  document.getElementById('tblBody').innerHTML = items.map(i => `
    <tr>
      <td><span class="tipo-${['a_receber','recebido'].includes(i.tipo) ? 'receita' : 'despesa'}">${tipoLabel(i.tipo)}</span></td>
      <td>${i.descricao || '-'}</td>
      <td>${i.categoria_nome || '-'}</td>
      <td style="font-weight:600">R$ ${fmt(i.valor)}</td>
      <td>${i.vencimento ? fmtDate(i.vencimento) : '-'}</td>
      <td><span class="badge badge-${i.status}">${i.status}</span></td>
      <td>
        <button class="btn btn-secondary btn-sm" onclick="editLanc('${i.id}')" title="Editar">&#9998;</button>
        ${i.status === 'pendente' ? `<button class="btn btn-primary btn-sm" onclick="confirmarLanc('${i.id}','${i.tipo}')" title="Confirmar">&#10003;</button>` : ''}
        <button class="btn btn-danger btn-sm" onclick="cancelarLanc('${i.id}')" title="Cancelar">&#10005;</button>
      </td>
    </tr>
  `).join('');
}

function clearFilters() {
  document.getElementById('fTipo').value = '';
  document.getElementById('fStatus').value = '';
  document.getElementById('fCategoria').value = '';
  document.getElementById('fDe').value = '';
  document.getElementById('fAte').value = '';
  loadLancamentos();
}

// ========== CRUD ==========
async function criarLancamento(e) {
  e.preventDefault();
  const form = new FormData(e.target);
  const body = { action: 'create' };
  for (const [k, v] of form) { if (v) body[k] = v; }

  try {
    await apiPost(body);
    toast('Lancamento criado com sucesso!');
    e.target.reset();
    switchTab('lancamentos');
  } catch (err) {
    toast('Erro ao criar: ' + err.message, true);
  }
}

async function editLanc(id) {
  try {
    const data = await api({ action: 'get', id });
    const item = Array.isArray(data) ? data[0] : data;
    const form = document.getElementById('formEdit');
    form.querySelector('[name=id]').value = item.id;
    form.querySelector('[name=tipo]').value = item.tipo;
    form.querySelector('[name=status]').value = item.status;
    form.querySelector('[name=descricao]').value = item.descricao || '';
    form.querySelector('[name=valor]').value = item.valor;
    form.querySelector('[name=vencimento]').value = item.vencimento ? item.vencimento.slice(0, 10) : '';
    form.querySelector('[name=categoria_id]').value = item.categoria_id || '';
    document.getElementById('modalEdit').classList.add('active');
  } catch (err) {
    toast('Erro ao carregar: ' + err.message, true);
  }
}

async function updateLancamento(e) {
  e.preventDefault();
  const form = new FormData(e.target);
  const body = { action: 'update' };
  for (const [k, v] of form) { if (v) body[k] = v; }

  try {
    await apiPost(body);
    toast('Lancamento atualizado!');
    closeModal();
    loadLancamentos();
  } catch (err) {
    toast('Erro ao atualizar: ' + err.message, true);
  }
}

async function confirmarLanc(id, tipo) {
  const newTipo = tipo === 'a_pagar' ? 'pago' : tipo === 'a_receber' ? 'recebido' : tipo;
  try {
    await apiPost({ action: 'update', id, tipo: newTipo, status: 'confirmado' });
    toast('Lancamento confirmado!');
    loadLancamentos();
    loadDashboard();
  } catch (err) {
    toast('Erro: ' + err.message, true);
  }
}

async function cancelarLanc(id) {
  if (!confirm('Cancelar este lancamento?')) return;
  try {
    await apiPost({ action: 'delete', id });
    toast('Lancamento cancelado.');
    loadLancamentos();
    loadDashboard();
  } catch (err) {
    toast('Erro: ' + err.message, true);
  }
}

function closeModal() {
  document.getElementById('modalEdit').classList.remove('active');
}

// ========== CATEGORIAS ==========
async function loadCategorias() {
  try {
    const data = await api({ action: 'categorias' });
    categorias = Array.isArray(data) ? data : [data];

    const opts = '<option value="">Selecione...</option>' + categorias.map(c =>
      `<option value="${c.id}">${c.nome} (${c.tipo})</option>`
    ).join('');

    document.getElementById('selCategoria').innerHTML = opts;
    document.getElementById('editCategoria').innerHTML = opts;
    document.getElementById('fCategoria').innerHTML = '<option value="">Todas categorias</option>' + categorias.map(c =>
      `<option value="${c.id}">${c.nome}</option>`
    ).join('');
  } catch (e) {
    console.error('Categorias error:', e);
  }
}

function loadCategoriasTab() {
  const tbody = document.getElementById('tblCats');
  if (categorias.length === 0) {
    tbody.innerHTML = '<tr><td colspan="3" style="color:var(--text3)">Nenhuma categoria.</td></tr>';
    return;
  }
  tbody.innerHTML = categorias.map(c => `
    <tr>
      <td>${c.id}</td>
      <td>${c.nome}</td>
      <td><span class="tipo-${c.tipo === 'receita' ? 'receita' : 'despesa'}">${c.tipo}</span></td>
    </tr>
  `).join('');
}

// ========== EXPORT ==========
async function exportCSV() {
  const { de, ate } = getperiodo();
  try {
    const res = await fetch(`${API_BASE}?action=export&de=${de}&ate=${ate}`);
    const data = await res.json();
    const csv = Array.isArray(data) ? data[0]?.csv : data.csv;
    if (!csv) { toast('Sem dados para exportar', true); return; }

    const blob = new Blob(['\uFEFF' + csv], { type: 'text/csv;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `lancamentos_${de}_${ate}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    toast('CSV exportado!');
  } catch (e) {
    toast('Erro ao exportar: ' + e.message, true);
  }
}

// ========== HELPERS ==========
function fmt(v) { return parseFloat(v || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
function fmtDate(d) { return d ? new Date(d).toLocaleDateString('pt-BR') : '-'; }
function tipoLabel(t) {
  const m = { a_pagar: 'A Pagar', a_receber: 'A Receber', pago: 'Pago', recebido: 'Recebido' };
  return m[t] || t;
}
function toast(msg, isError) {
  const el = document.getElementById('toast');
  el.textContent = msg;
  el.className = 'toast show' + (isError ? ' error' : '');
  setTimeout(() => el.className = 'toast', 3000);
}
